INSERT INTO "world"."locales_broadcast_text" ("entry", "male_text_loc1", "male_text_loc2", "male_text_loc3", "male_text_loc4", "male_text_loc5", "male_text_loc6", "male_text_loc7", "male_text_loc8", "female_text_loc1", "female_text_loc2", "female_text_loc3", "female_text_loc4", "female_text_loc5", "female_text_loc6", "female_text_loc7", "female_text_loc8") VALUES
(4979, '', '', '', '', '', '', '', '', '알겠어요!', 'Vous l''avez !', 'Alles klar!', '没问题！', '沒問題！', '¡Lo has conseguido!', '¡Lo has conseguido!', 'Так и быть!'),
(4980, '', '', '', '', '', '', '', '', '곧 가겠어요!', 'Ça vient !', 'Kommt sofort!', '马上就来了！', '馬上就來了！', '¡Ahora mismo voy!', '¡Ahora mismo voy!', 'Уже иду!'),
(4981, '', '', '', '', '', '', '', '', '곧 갈게요...', 'J''apporte ça tout de suite !', 'Ich bringe es sofort, Baby...', '宝贝，我马上就过来……', '寶貝，我馬上就過來……', 'Ahora mismo te lo llevo, cariño...', 'Ahora mismo te lo llevo, cariño...', 'Сейчас принесу, золотце.'),
(4983, '', '', '', '', '', '', '', '', '네, 알겠습니다.', 'Oui $gmonseigneur:madame;.', 'Ja, $gwerter Herr:holde Dame;.', '好的，$g先生:女士;。', '好的，$g先生:女士;。', 'Sí, $gseñor:señora;.', 'Sí, $gseñor:señora;.', 'Да, $gгосподин:госпожа;.'),
(4984, '이봐, 나그마라! 검은무쇠단 맥주 한 잔 갖다 주지 않겠어?', 'Hé, Nagmara ! Ça vous dit, une chope de bière sombrefer ?', 'He, Nagmara! Wie wäre es mit einem Becher Dunkeleisenbier?', '嘿，娜玛拉！来一杯黑铁啤酒怎么样？', '嘿，娜瑪拉！來一杯黑鐵啤酒怎麼樣？', '¡Eh, Nagmara! ¿Qué te parece una jarra de cerveza Hierro Negro?', '¡Eh, Nagmara! ¿Qué te parece una jarra de cerveza Hierro Negro?', 'Эй, Нагмара! Как насчет кружечки эля Черного Железа?', '이봐, 나그마라! 검은무쇠단 맥주 한 잔 갖다 주지 않겠어?', 'Hé, Nagmara ! Ça vous dit, une chope de bière sombrefer ?', 'He, Nagmara! Wie wäre es mit einem Becher Dunkeleisenbier?', '嘿，娜玛拉！来一杯黑铁啤酒怎么样？', '嘿，娜瑪拉！來一杯黑鐵啤酒怎麼樣？', '¡Eh, Nagmara! ¿Qué te parece una jarra de cerveza Hierro Negro?', '¡Eh, Nagmara! ¿Qué te parece una jarra de cerveza Hierro Negro?', 'Эй, Нагмара! Как насчет кружечки эля Черного Железа?'),
(4985, '나그마라! 양고기는 아직 남았나?', 'Nagmara ! Il reste du mouton ?', 'Nagmara! Ist noch Hammelfleisch übrig?', '娜玛拉！还有羊肉吗？', '娜瑪拉！還有羊肉嗎？', '¡Nagmara! ¿Te queda alguna oveja?', '¡Nagmara! ¿Te queda algo de cordero?', 'Нагмара! А у нас баранина еще осталась?', '나그마라! 양고기는 아직 남았나?', 'Nagmara ! Il reste du mouton ?', 'Nagmara! Ist noch Hammelfleisch übrig?', '娜玛拉！还有羊肉吗？', '娜瑪拉！還有羊肉嗎？', '¡Nagmara! ¿Te queda alguna oveja?', '¡Nagmara! ¿Te queda algo de cordero?', 'Нагмара! А у нас баранина еще осталась?'),
(4986, '이봐, 플러거한테 맥주가 더 필요하다고 전해주게. 아무리 마셔도 모자라다니까!', 'Mademoiselle, dites à Plugger que je veux encore de sa bière ! Je n''en ai jamais assez !', 'Herrin, sagt Plugger, dass ich noch mehr von seinem Bier möchte. Ich bekomme nicht genug davon!', '小姐，请你告诉普拉格，我想要更多的啤酒。这些远远不够！', '小姐，請你告訴普拉格，我想要更多的啤酒。這些遠遠不夠！', 'Maestra, dile a Plugger que quiero más cerveza de esta. ¡Me encanta!', 'Coima, dile a Plugger que quiero más cerveza de esta. ¡Me encanta!', 'Хозяйка, скажите Стукарю, чтобы прислал мне еще эля! Мне его вечно не хватает.', '이봐, 플러거한테 맥주가 더 필요하다고 전해주게. 아무리 마셔도 모자라다니까!', 'Mademoiselle, dites à Plugger que je veux encore de sa bière ! Je n''en ai jamais assez !', 'Herrin, sagt Plugger, dass ich noch mehr von seinem Bier möchte. Ich bekomme nicht genug davon!', '小姐，请你告诉普拉格，我想要更多的啤酒。这些远远不够！', '小姐，請你告訴普拉格，我想要更多的啤酒。這些遠遠不夠！', 'Maestra, dile a Plugger que quiero más cerveza de esta. ¡Me encanta!', 'Coima, dile a Plugger que quiero más cerveza de esta. ¡Me encanta!', 'Хозяйка, скажите Стукарю, чтобы прислал мне еще эля! Мне его вечно не хватает.'),
(4987, '이봐, 나그마라. 그거 한 조각 나눠주는 게 어때...', 'Hé Nag, et si vous me donniez un morceau de ce truc ?', 'He, Nag, würdet Ihr mir davon wohl eine Scheibe abschneiden...', '嘿，我说，娜玛拉，你能切给我一块吗……', '嘿，我說，娜瑪拉，你能切給我一塊嗎……', 'Oye, Nag, qué tal si me cortas una rebanada de eso...', 'Oye, Nag, qué tal si me cortas una rebanada de eso...', 'Эй, зануда, отрежь-ка и мне кусочек…', '이봐, 나그마라. 그거 한 조각 나눠주는 게 어때...', 'Hé Nag, et si vous me donniez un morceau de ce truc ?', 'He, Nag, würdet Ihr mir davon wohl eine Scheibe abschneiden...', '嘿，我说，娜玛拉，你能切给我一块吗……', '嘿，我說，娜瑪拉，你能切給我一塊嗎……', 'Oye, Nag, qué tal si me cortas una rebanada de eso...', 'Oye, Nag, qué tal si me cortas una rebanada de eso...', 'Эй, зануда, отрежь-ка и мне кусочек…'),
(4988, '요리를 배우고 싶습니다.', 'J''aimerais apprendre à cuisiner.', 'Ich würde gern Kochunterricht bekommen.', '我想进行烹饪训练。', '我想進行烹飪訓練。', 'Me gustaría recibir instrucción en el arte de cocinar.', 'Me gustaría recibir instrucción en el arte de cocinar.', 'Я бы хотел учиться кулинарии.', '요리를 배우고 싶습니다.', 'J''aimerais apprendre à cuisiner.', 'Ich würde gern Kochunterricht bekommen.', '我想进行烹饪训练。', '我想進行烹飪訓練。', 'Me gustaría recibir instrucción en el arte de cocinar.', 'Me gustaría recibir instrucción en el arte de cocinar.', 'Я бы хотела учиться кулинарии.'),
(4989, '안녕하시오, $n. 요리에 대해 배우고 싶거든 언제든 날 찾아오시오.', 'Bonjour, $n. Si vous voulez apprendre une chose ou deux sur la cuisine, venez me voir quand vous voulez.', 'Hallo, $n. Wenn Ihr das eine oder andere über das Kochen lernen möchtet, schaut einfach bei mir rein.', '你好，$n。如果你想学习烹饪技巧的话，可以随时来找我。', '你好，$n。如果你想學習烹飪技巧的話，可以隨時來找我。', 'Hola, $n. Si te interesa aprender algún truco de cocina, ven a verme cuando quieras.', 'Hola, $n. Si te interesa aprender algún truco de cocina, ven a verme cuando quieras.', 'Здравствуйте, $n. Если вы хотите научиться готовить, то вы пришли по адресу.', '', '', '', '', '', '', '', ''),
(4990, '', '', '', '', '', '', '', '', '<여군주 프레스톨이 노려봅니다.>', '<Dame Prestor vous fixe.>', '<Lady Prestor schaut Euch böse an.>', '<普瑞斯托女士怒视着你。>', '<普瑞斯托女士怒視著你。>', '<Lady Prestor te mira.>', '<Lady Prestor te mira.>', '<Леди Престор сердито смотрит на вас.>'),
(4991, '무례함을 용서해주십시오, 프레스톨님. 하지만 볼바르님께서 당신의 조언을 구하라 하셨습니다.', 'Pardon pour cette intrusion, dame Prestor, mais le généralissime Bolvar m''a suggéré de solliciter vos conseils.', 'Bitte entschuldigt die Störung, Lady Prestor, aber Hochlord Bolvar schlug vor, dass ich Euren Rat suche.', '普瑞斯托女士，请原谅我的冒昧，但是伯瓦尔·弗塔根公爵让我来寻求您的建议。', '普瑞斯托女士，請原諒我的冒昧，但是伯瓦爾·弗塔根公爵讓我來尋求您的建議。', 'Perdón por la intromisión, Lady Prestor, pero el alto señor Bolvar me sugirió que pidiera su consejo.', 'Perdón por la intromisión, Lady Prestor, pero el alto señor Bolvar me sugirió que pidiera su consejo.', 'Приношу извинения за вторжение, леди Престор, но верховный лорд Болвар предложил мне спросить у вас совета.', '무례함을 용서해주십시오, 프레스톨님. 하지만 볼바르님께서 당신의 조언을 구하라 하셨습니다.', 'Pardon pour cette intrusion, dame Prestor, mais le généralissime Bolvar m''a suggéré de solliciter vos conseils.', 'Bitte entschuldigt die Störung, Lady Prestor, aber Hochlord Bolvar schlug vor, dass ich Euren Rat suche.', '普瑞斯托女士，请原谅我的冒昧，但是伯瓦尔·弗塔根公爵让我来寻求您的建议。', '普瑞斯托女士，請原諒我的冒昧，但是伯瓦爾·弗塔根公爵讓我來尋求您的建議。', 'Perdón por la intromisión, Lady Prestor, pero el alto señor Bolvar me sugirió que pidiera su consejo.', 'Perdón por la intromisión, Lady Prestor, pero el alto señor Bolvar me sugirió que pidiera su consejo.', 'Приношу извинения за вторжение, леди Престор, но верховный лорд Болвар предложил мне спросить у вас совета.'),
(4992, '', '', '', '', '', '', '', '', '난 바로 그대 곁에 서 있었습니다, 어리석기는... 그대가 찾는 게 뭔지 알고 있단 말입니다.', 'J''étais juste à côté de vous, imbécile. Je sais ce que je vous cherchez.', 'Ich stand direkt neben Euch, Schwachkopf. Ich weiß, was Ihr sucht.', '我就站在你旁边，笨蛋。我知道你在找什么。', '我就站在你旁邊，笨蛋。我知道你在找什麼。', 'Estaba justo al lado tuyo, imbécil. Sé lo que buscas.', 'Estaba justo al lado tuyo, imbécil. Sé lo que buscas.', 'Я стояла возле тебя, тупица, и знаю, чего тебе надо!'),
(4993, '용서하십시오, 프레스톨님.', 'Mille excuses, dame Prestor.', 'Entschuldigt bitte, Lady Prestor.', '很抱歉，普瑞斯托女士。', '很抱歉，普瑞斯托女士。', 'Discúlpame, Lady Prestor.', 'Discúlpame, Lady Prestor.', 'Мои извинения, леди Престор.', '용서하십시오, 프레스톨님.', 'Mille excuses, dame Prestor.', 'Entschuldigt bitte, Lady Prestor.', '很抱歉，普瑞斯托女士。', '很抱歉，普瑞斯托女士。', 'Discúlpame, Lady Prestor.', 'Discúlpame, Lady Prestor.', 'Мои извинения, леди Престор.'),
(4994, '', '', '', '', '', '', '', '', '그댄 망상에 빠진 집정관과 대다수가 더위로 고생하고 있을 하층민 야영지를 달래기 위해 우리의 전체적인 방어력을 낮추려는 것이겠지요.', 'Vous cherchez à affaiblir nos défenses générales pour apaiser un magistrat paranoïaque et un campement de truands qui souffrent sans doute d''une insolation.', 'Ihr wollt unsere globale Verteidigung schwächen, um einem paranoiden Magistrat und Gesindel zu gefallen, die höchstwahrscheinlich an Hitzschlag leiden.', '你是说为了满足一个妄想狂的地方官和一群没准正在遭受中暑之苦的乌合之众的愿望，我们就得把世界各地的部队都调回来，然后给他派过去吗？', '你是說為了滿足一個妄想狂的地方官和一群沒准正在遭受中暑之苦的烏合之眾的願望，我們就得把世界各地的部隊都調回來，然後給他派過去嗎？', 'Intentas reducir nuestras defensas globales para apaciguar a un magistrado paranoico y un campamento de gentuza que probablemente está padeciendo insolación.', 'Intentas reducir nuestras defensas globales para apaciguar a un magistrado paranoico y un campamento de gentuza que probablemente está padeciendo insolación.', 'Ты хочешь ослабить нашу оборону ради чиновников-параноиков и всякого безумного сброда из лагеря.'),
(4995, '송구스러운 말씀입니다만 결코 그런 의도가 아니었습니다, 프레스톨님.', 'Je vous demande pardon, dame Prestor. Telle n''était pas mon intention.', 'Pardon, Lady Prestor. Das war nicht meine Absicht.', '普瑞斯托女士，请你原谅。这并非我的本意。', '普瑞斯托女士，請你原諒。這並非我的本意。', 'Pido que me disculpes, Lady Prestor. Esa no era mi intención.', 'Pido que me disculpes, Lady Prestor. Esa no era mi intención.', 'Молю о прощении, госпожа Престор. Мои намерения были совершенно иными.', '송구스러운 말씀입니다만 결코 그런 의도가 아니었습니다, 프레스톨님.', 'Je vous demande pardon, dame Prestor. Telle n''était pas mon intention.', 'Pardon, Lady Prestor. Das war nicht meine Absicht.', '普瑞斯托女士，请你原谅。这并非我的本意。', '普瑞斯托女士，請你原諒。這並非我的本意。', 'Pido que me disculpes, Lady Prestor. Esa no era mi intención.', 'Pido que me disculpes, Lady Prestor. Esa no era mi intención.', 'Молю о прощении, госпожа Престор. Мои намерения были совершенно иными.'),
(4996, '', '', '', '', '', '', '', '', '당연히 아니겠지요. 그대와 같은 "모험가"라는 자들은 백성과 왕실 사이에 벌어지는 정치 드라마의 피해자인 경우가 많으니까 말입니다.$B$B내가 해 줄 말이라곤 다른 걸 찾아보라는 것입니다. 더 정확히 말해서 직업을 바꾸어보라는 겁니다.$B$B이 세계에는 지금도 영웅이 충분하답니다.', 'Bien sûr que non, mon $gami:amie;. Vous autres, les "aventuriers", vous êtes souvent victimes des circonstances ; sujets aux drames politiques qui tendent à se nouer entre les citoyens et le trône.$B$BJe vous conseille de chercher autre chose. Plus précisément : une nouvelle carrière.$B$BIl y a assez de héros dans ce monde.', 'Natürlich nicht, $glieber Junge:liebes Mädchen;. Ihr Abenteurertypen seid häufig Opfer der Umstände und den politischen Dramen ausgeliefert, die sich zwischen den Bürgern und dem Adel abspielen.$B$BMein Rat für Euch ist daher, sucht etwas anderes, genauer: einen neuen Beruf.$B$BDiese Welt hat bereits genügend Helden.', '当然不是，亲爱的$g小伙子:姑娘;。你这种“冒险者”类型的$c经常成为政治的牺牲品，被政治家玩弄于股掌之间而毫无察觉。$B$B我给你的建议，就是去做一些更加具体的事情：找份新工作。$B$B这个世界已经有太多的英雄了。', '當然不是，親愛的$g小夥子:姑娘;。你這種「冒險者」類型的$c經常成為政治的犧牲品，被政治家玩弄於股掌之間而毫無察覺。$B$B我給你的建議，就是去做一些更加具體的事情：找份新工作。$B$B這個世界已經有太多的英雄了。', 'Por supuesto que no, $gchico:chica;. Vosotros, los aventureros, a menudo sois víctimas de las circunstancias; sujetos al drama político que suele desarrollarse entre los ciudadanos y la realeza.$B$BMi consejo es que busques algo más, específicamente, una nueva profesión.$B$BEste mundo ya tiene suficientes héroes.', 'Por supuesto que no, $gchico:chica;. Ustedes, los aventureros, a menudo son víctimas de las circunstancias; sujetos al drama político que suele desarrollarse entre los ciudadanos y la realeza.$B$BMi consejo es que busques algo más, específicamente, una nueva profesión.$B$BEste mundo ya tiene suficientes héroes.', 'Разумеется нет, $gмилый юноша:милая девушка;. Такие искатели приключений часто оказываются втянутыми во всякие политические скандалы и интриги между простыми жителями и дворянством.$b$bМой вам добрый совет: найдите себе хорошую работу.$b$bГероев в этом мире – как грязи.'),
(4997, '흠, 시간을 내주셔서 감사합니다, 프레스톨님.', 'Merci de m''avoir consacré du temps, dame Prestor.', 'Ich danke Euch für die Zeit, die Ihr aufgewendet habt, Lady Prestor.', '普瑞斯托女士您费时了，谢谢你。', '普瑞斯托女士您費時了，謝謝你。', 'Gracias por tu tiempo, Lady Prestor.', 'Gracias por tu tiempo, Lady Prestor.', 'Спасибо за потраченное время, госпожа Престор.', '흠, 시간을 내주셔서 감사합니다, 프레스톨님.', 'Merci de m''avoir consacré du temps, dame Prestor.', 'Ich danke Euch für die Zeit, die Ihr aufgewendet habt, Lady Prestor.', '普瑞斯托女士您费时了，谢谢你。', '普瑞斯托女士您費時了，謝謝你。', 'Gracias por tu tiempo, Lady Prestor.', 'Gracias por tu tiempo, Lady Prestor.', 'Спасибо за потраченное время, госпожа Престор.'),
